// Define agents to run in parallel
const agents = [
  { name: "agent-java-architect", description: "Java/Spring architecture analysis" },
  { name: "agent-business-logic-analyst", description: "Business rules extraction" },
  { name: "agent-ui-analysis-specialist", description: "Frontend component analysis" },
  { name: "agent-security-analyst", description: "Security vulnerability assessment" },
  { name: "agent-performance-analyst", description: "Performance optimization analysis" }
];

const session_id = `parallel-${Date.now()}`;

return agents.map(agent => ({
  json: {
    agent_name: agent.name,
    description: agent.description,
    session_id: session_id,
    timeout: 300
  }
}));

// Compile results from all agents
const items = $input.all();
const results = {
  timestamp: new Date().toISOString(),
  total_agents: items.length,
  successful: 0,
  failed: 0,
  agents: []
};

for (const item of items) {
  const data = item.json;
  const agentName = data.original_name || data.agent || 'unknown';

  if (data.success) {
    results.successful++;
    results.agents.push({
      name: agentName,
      status: 'completed',
      execution_time: data.execution_time || 0
    });
  } else {
    results.failed++;
    results.agents.push({
      name: agentName,
      status: 'failed',
      error: data.error || 'Unknown error'
    });
  }
}

results.message = `Parallel execution complete: ${results.successful}/${results.total_agents} agents succeeded`;
results.success_rate = Math.round((results.successful / results.total_agents) * 100);

return [{ json: results }];
